function UserPosts({ userId }: { userId: string | null }) {
  const { data: user, isLoading: userLoading } = useQuery({
    queryKey: ['user', userId ?? 'none'],
    queryFn: () => fetchUser(userId!),
    enabled: userId !== null,
  });

  const { data: posts, isLoading: postsLoading } = useQuery({
    queryKey: ['posts', 'by-user', user?.id ?? 'none'],
    queryFn: () => fetchPostsByUser(user!.id),
    // Only fetch posts once user data is available
    enabled: !!user,
  });

  if (!userId) return <p>Select a user to view their posts.</p>;
  if (userLoading) return <p>Loading user...</p>;
  if (postsLoading) return <p>Loading posts...</p>;

  return (
    <section>
      <h1>{user.name}'s Posts</h1>
      <ul>
        {posts?.map((post) => (
          <li key={post.id}>{post.title}</li>
        ))}
      </ul>
    </section>
  );
}

import { useQuery, useQueryClient } from '@tanstack/react-query';

function OrderDetails({ orderId }: { orderId: string }) {
  const queryClient = useQueryClient();

  const { data: order } = useQuery({
    queryKey: ['orders', orderId],
    queryFn: () => fetchOrder(orderId),
  });

  // Second query depends on the first â€” reads customerId from cache
  const { data: customer } = useQuery({
    queryKey: ['customers', order?.customerId],
    queryFn: async () => {
      // order is available from the cache once query 1 succeeds
      const customerId = order!.customerId;
      const res = await fetch(`/api/customers/${customerId}`);
      return res.json();
    },
    enabled: !!order?.customerId,
  });

  return (
    <div>
      <h2>Order #{orderId}</h2>
      <p>Customer: {customer?.name}</p>
    </div>
  );
}

function OrderWithItems({ orderId }: { orderId: string }) {
  const { data: order, isError: orderError } = useQuery({
    queryKey: ['orders', orderId],
    queryFn: () => fetchOrder(orderId),
  });

  const { data: items, isError: itemsError } = useQuery({
    queryKey: ['orders', orderId, 'items'],
    queryFn: () => fetchOrderItems(orderId),
    enabled: !!order,
  });

  if (orderError) return <p className="error">Failed to load order.</p>;

  return (
    <div>
      <h1>Order #{order?.id}</h1>
      <p>Status: {order?.status}</p>

      {itemsError && (
        <p className="error">Could not load items, but order details are shown.</p>
      )}

      {items?.map((item) => (
        <div key={item.id}>{item.productName} x {item.quantity}</div>
      ))}
    </div>
  );
}
